//! Lectura y escritura del archivo de partida (formato texto `clave=valor`).

use std::collections::BTreeMap;
use std::fmt;

use crate::config::{MAX_STACK, SAVE_VERSION};

/// Datos de una partida guardada.
#[derive(Debug, Clone, PartialEq, Eq, Default)]
pub struct SaveData {
    /// Versión del formato.
    pub version: u32,
    /// Nombre del jugador.
    pub player: String,
    /// Oro del jugador.
    pub gold: u32,
    /// Objetos: nombre → cantidad.
    pub items: BTreeMap<String, u32>,
}

/// Errores al leer una partida. `line` es el número de línea (empezando en 1).
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum SaveError {
    /// Línea sin `=`.
    Malformed { line: usize },
    /// Clave desconocida.
    UnknownKey { line: usize, key: String },
    /// Número inválido (no numérico, negativo, fuera de rango o cantidad 0).
    InvalidNumber { line: usize, value: String },
    /// Falta un campo obligatorio (`"version"` o `"player"`).
    MissingField(&'static str),
    /// Versión distinta de la soportada.
    UnsupportedVersion(u32),
    /// Un objeto supera el tamaño máximo de pila (sumando todas sus líneas).
    StackOverflow { item: String },
}

impl fmt::Display for SaveError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            SaveError::Malformed { line } => write!(f, "línea {line}: falta '='"),
            SaveError::UnknownKey { line, key } => write!(f, "línea {line}: clave desconocida '{key}'"),
            SaveError::InvalidNumber { line, value } => write!(f, "línea {line}: número inválido '{value}'"),
            SaveError::MissingField(name) => write!(f, "falta el campo '{name}'"),
            SaveError::UnsupportedVersion(v) => write!(f, "versión {v} no soportada"),
            SaveError::StackOverflow { item } => write!(f, "demasiadas unidades de '{item}'"),
        }
    }
}

impl std::error::Error for SaveError {}

/// Lee una partida. Ver docs/tasks/RS-401.md.
pub fn parse_save(input: &str) -> Result<SaveData, SaveError> {
    let mut data = SaveData::default();
    let mut version = None;
    let mut player = None;

    for (index, raw) in input.lines().enumerate() {
        let line = index + 1;
        let text = raw.trim();
        if text.is_empty() || text.starts_with('#') {
            continue;
        }
        let (key, value) = text.split_once('=').ok_or(SaveError::Malformed { line })?;
        let key = key.trim();
        let value = value.trim();
        match key {
            "version" => version = Some(parse_number(line, value)?),
            "player" => player = Some(value.to_string()),
            "gold" => data.gold = parse_number(line, value)?,
            "item" => {
                let (name, amount) = value.split_once(':').ok_or(SaveError::Malformed { line })?;
                let amount = amount.trim();
                let qty = parse_number(line, amount)?;
                if qty == 0 {
                    return Err(SaveError::InvalidNumber { line, value: amount.to_string() });
                }
                let name = name.trim();
                let total = data.items.get(name).copied().unwrap_or(0).saturating_add(qty);
                if total > MAX_STACK {
                    return Err(SaveError::StackOverflow { item: name.to_string() });
                }
                data.items.insert(name.to_string(), total);
            }
            _ => return Err(SaveError::UnknownKey { line, key: key.to_string() }),
        }
    }

    let version = version.ok_or(SaveError::MissingField("version"))?;
    if version != SAVE_VERSION {
        return Err(SaveError::UnsupportedVersion(version));
    }
    data.version = version;
    data.player = match player {
        Some(name) if !name.is_empty() => name,
        _ => return Err(SaveError::MissingField("player")),
    };
    Ok(data)
}

/// Convierte un valor a `u32`, o `InvalidNumber` si no es válido.
fn parse_number(line: usize, value: &str) -> Result<u32, SaveError> {
    value
        .parse()
        .map_err(|_| SaveError::InvalidNumber { line, value: value.to_string() })
}

/// Escribe una partida en el formato de texto (ya implementado).
pub fn to_save_string(data: &SaveData) -> String {
    let mut out = format!("version={}\nplayer={}\ngold={}\n", data.version, data.player, data.gold);
    for (name, qty) in &data.items {
        out.push_str(&format!("item={name}:{qty}\n"));
    }
    out
}
